18	      // attached run is keeping - those come from the plugin on every appear.
19	      (() => {
20	        const { streamDeckClient } = SDPIComponents;
21	        const field = document.getElementById("field");
22	        const FIXED = [
23	          ["score", "Score"],
24	          ["unit", "Unit"],
25	          ["clock", "Clock"],
26	          ["latest", "Last result"],
27	          ["leader", "Leader"],
28	        ];
29	        let current = null;
30	
31	        const option = (value, label) => {
32	          const o = document.createElement("option");
33	          o.value = JSON.stringify(value);
34	          o.textContent = label;
35	          return o;
36	        };
37	
38	        const fill = (counters, resources) => {
39	          field.replaceChildren(option(null, "Set up"), ...FIXED.map(([v, l]) => option(v, l)));
