41	          for (const r of resources) field.appendChild(option({ resource: r.id }, r.label));
42	          show();
43	        };
44	
45	        const show = () => {
46	          const chosen = JSON.stringify(current ?? null);
47	          const match = [...field.options].find((o) => o.value === chosen);
48	          if (match) field.value = match.value;
49	        };
50	
51	        field.addEventListener("change", () => {
52	          current = JSON.parse(field.value);
53	          streamDeckClient.setSettings(current ? { field: current } : {});
54	        });
55	
56	        streamDeckClient.sendToPropertyInspector.subscribe(({ payload }) => {
57	          if (payload?.t === "fields") fill(payload.counters ?? [], payload.resources ?? []);
58	        });
